#!/usr/bin/env bun
import { readFileSync } from "fs";

function die(msg: string): never {
  process.stderr.write(msg.endsWith("\n") ? msg : msg + "\n");
  process.exit(1);
}

type Task = { id: string; duration: number; dependsOn: string[] };

function fail(msg: string): never {
  die("error: " + msg);
}

function validate(raw: unknown): Task[] {
  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
    fail("input must be a JSON object with a \"tasks\" array");
  }
  const root = raw as Record<string, unknown>;
  if (!Array.isArray(root.tasks)) {
    fail("\"tasks\" must be an array");
  }
  const tasks: Task[] = [];
  const ids = new Set<string>();
  for (let i = 0; i < root.tasks.length; i++) {
    const t = root.tasks[i];
    if (typeof t !== "object" || t === null || Array.isArray(t)) {
      fail(`task at index ${i} must be an object`);
    }
    const o = t as Record<string, unknown>;
    if (typeof o.id !== "string" || o.id.length === 0) {
      fail(`task at index ${i} has invalid id (must be a non-empty string)`);
    }
    if (ids.has(o.id)) {
      fail(`duplicate task id: ${JSON.stringify(o.id)}`);
    }
    ids.add(o.id);
    if (typeof o.duration !== "number" || !Number.isFinite(o.duration) || o.duration < 0) {
      fail(`task ${JSON.stringify(o.id)} has invalid duration (must be a finite non-negative number)`);
    }
    let deps: unknown = o.dependsOn;
    if (deps === undefined) deps = [];
    if (!Array.isArray(deps)) {
      fail(`task ${JSON.stringify(o.id)}: dependsOn must be an array of strings`);
    }
    const seen = new Set<string>();
    for (const d of deps) {
      if (typeof d !== "string") {
        fail(`task ${JSON.stringify(o.id)}: dependsOn entries must be strings`);
      }
      if (d === o.id) {
        fail(`task ${JSON.stringify(o.id)} cannot depend on itself`);
      }
      if (seen.has(d)) {
        fail(`task ${JSON.stringify(o.id)} has duplicate dependency ${JSON.stringify(d)}`);
      }
      seen.add(d);
    }
    tasks.push({ id: o.id, duration: o.duration, dependsOn: deps as string[] });
  }
  for (const t of tasks) {
    for (const d of t.dependsOn) {
      if (!ids.has(d)) {
        fail(`task ${JSON.stringify(t.id)} depends on unknown id ${JSON.stringify(d)}`);
      }
    }
  }
  return tasks;
}

function findCycle(
  ids: string[],
  deps: Map<string, string[]>,
  remaining: Set<string>,
): string[] | null {
  const sortedRemaining = ids.filter((id) => remaining.has(id)).sort();
  const adj = (u: string) => deps.get(u)!.filter((v) => remaining.has(v)).sort();
  for (const start of sortedRemaining) {
    const path: string[] = [];
    const onPath = new Set<string>();
    let found: string[] | null = null;
    const dfs = (u: string): boolean => {
      path.push(u);
      onPath.add(u);
      for (const v of adj(u)) {
        if (onPath.has(v)) {
          const idx = path.indexOf(v);
          found = path.slice(idx).concat(v);
          return true;
        }
        if (dfs(v)) return true;
      }
      path.pop();
      onPath.delete(u);
      return false;
    };
    dfs(start);
    if (found) return found;
  }
  return null;
}

function plan(tasks: Task[]): Record<string, unknown> {
  const ids = tasks.map((t) => t.id);
  const duration = new Map<string, number>();
  const deps = new Map<string, string[]>();
  const dependents = new Map<string, string[]>();
  for (const t of tasks) {
    duration.set(t.id, t.duration);
    deps.set(t.id, t.dependsOn.slice());
    dependents.set(t.id, []);
  }
  for (const t of tasks) {
    for (const d of t.dependsOn) dependents.get(d)!.push(t.id);
  }

  const indeg = new Map<string, number>();
  for (const t of tasks) indeg.set(t.id, t.dependsOn.length);

  // Topological order (Kahn) with lexicographic tie-break.
  const ready: string[] = ids.filter((id) => indeg.get(id) === 0).sort();
  const order: string[] = [];
  while (ready.length > 0) {
    ready.sort();
    const id = ready.shift()!;
    order.push(id);
    for (const s of dependents.get(id)!) {
      indeg.set(s, indeg.get(s)! - 1);
      if (indeg.get(s) === 0) ready.push(s);
    }
  }

  if (order.length < ids.length) {
    const remaining = new Set<string>(ids);
    for (const id of order) remaining.delete(id);
    const cycle = findCycle(ids, deps, remaining);
    if (cycle) {
      die("error: dependency cycle detected: " + cycle.join(" -> ") + "\n");
    }
    die("error: dependency cycle detected\n");
  }

  // Layers: earliest layer after all dependencies.
  const layer = new Map<string, number>();
  for (const id of order) {
    let l = 0;
    for (const d of deps.get(id)!) l = Math.max(l, layer.get(d)! + 1);
    layer.set(id, l);
  }
  const layers: string[][] = [];
  for (const id of order) {
    const l = layer.get(id)!;
    while (layers.length <= l) layers.push([]);
    layers[l].push(id);
  }
  for (const l of layers) l.sort();

  // Earliest start/finish with unlimited parallelism.
  const earliest: Record<string, { start: number; finish: number }> = {};
  for (const id of order) {
    let start = 0;
    for (const d of deps.get(id)!) start = Math.max(start, earliest[d].finish);
    earliest[id] = { start, finish: start + duration.get(id)! };
  }

  let totalDuration = 0;
  for (const id of order) totalDuration = Math.max(totalDuration, earliest[id].finish);

  // Critical path: lexicographically smallest full id sequence whose
  // durations sum to totalDuration.
  const reachable = new Map<string, boolean>();
  for (let i = order.length - 1; i >= 0; i--) {
    const id = order[i];
    let r = earliest[id].finish === totalDuration;
    for (const s of dependents.get(id)!) {
      if (earliest[id].finish === earliest[s].start && reachable.get(s)!) r = true;
    }
    reachable.set(id, r);
  }

  const sortedIds = ids.slice().sort();
  const criticalPath: string[] = [];
  if (ids.length > 0) {
    let cur: string | null = null;
    for (const id of sortedIds) {
      if (earliest[id].start === 0 && reachable.get(id)!) {
        cur = id;
        break;
      }
    }
    while (cur !== null) {
      criticalPath.push(cur);
      if (earliest[cur].finish === totalDuration) break;
      let next: string | null = null;
      for (const s of dependents.get(cur)!.slice().sort()) {
        if (earliest[cur].finish === earliest[s].start && reachable.get(s)!) {
          next = s;
          break;
        }
      }
      cur = next;
    }
  }

  return {
    order,
    layers,
    earliest,
    totalDuration,
    criticalPath,
  };
}

function main(): void {
  const args = process.argv.slice(2);
  if (args.length !== 2 || args[0] !== "plan") {
    fail("usage: bun run src/cli.ts plan INPUT.json");
  }
  const file = args[1];
  let text: string;
  try {
    text = readFileSync(file, "utf8");
  } catch (e) {
    fail(`cannot read file ${JSON.stringify(file)}: ${(e as Error).message}`);
  }
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch (e) {
    fail(`invalid JSON in ${JSON.stringify(file)}: ${(e as Error).message}`);
  }
  const tasks = validate(raw);
  const result = plan(tasks);
  process.stdout.write(JSON.stringify(result, null, 2) + "\n");
}

main();

