#!/usr/bin/env bun
// Self-tests for the dependency planner CLI.
import { spawnSync } from "child_process";
import { writeFileSync, mkdtempSync, rmSync } from "fs";
import { tmpdir } from "os";
import { join } from "path";

const dir = mkdtempSync(join(tmpdir(), "dp-test-"));
let pass = 0;
let fail = 0;

function run(input: unknown): { code: number; stdout: string; stderr: string } {
  const f = join(dir, "in.json");
  writeFileSync(f, JSON.stringify(input));
  const r = spawnSync("bun", ["run", "src/cli.ts", "plan", f], { encoding: "utf8" });
  return { code: r.status ?? 1, stdout: r.stdout, stderr: r.stderr };
}

function ok(name: string, cond: boolean, extra = "") {
  if (cond) {
    pass++;
  } else {
    fail++;
    console.error(`FAIL: ${name} ${extra}`);
  }
}

function expectOk(name: string, input: unknown, check: (o: Record<string, unknown>) => boolean) {
  const r = run(input);
  if (r.code !== 0) {
    ok(name, false, `exit=${r.code} stderr=${r.stderr.trim()}`);
    return;
  }
  let o: Record<string, unknown>;
  try {
    o = JSON.parse(r.stdout);
  } catch (e) {
    ok(name, false, `bad json output: ${r.stdout}`);
    return;
  }
  ok(name, check(o), JSON.stringify(o));
}

function expectErr(name: string, input: unknown, re: RegExp) {
  const r = run(input);
  ok(name, r.code !== 0 && re.test(r.stderr), `exit=${r.code} stderr=${r.stderr.trim()}`);
}

// 1. Basic chain.
expectOk("basic", { tasks: [{ id: "build", duration: 3, dependsOn: ["lint"] }, { id: "lint", duration: 1 }] }, (o) =>
  JSON.stringify(o.order) === JSON.stringify(["lint", "build"]) &&
  o.totalDuration === 4 &&
  JSON.stringify(o.criticalPath) === JSON.stringify(["lint", "build"]),
);

// 2. Diamond picks longer branch for critical path.
expectOk("diamond", {
  tasks: [
    { id: "a", duration: 1 },
    { id: "b", duration: 2, dependsOn: ["a"] },
    { id: "c", duration: 3, dependsOn: ["a"] },
    { id: "d", duration: 1, dependsOn: ["b", "c"] },
  ],
}, (o) =>
  JSON.stringify(o.order) === JSON.stringify(["a", "b", "c", "d"]) &&
  JSON.stringify(o.layers) === JSON.stringify([["a"], ["b", "c"], ["d"]]) &&
  o.totalDuration === 5 &&
  JSON.stringify(o.criticalPath) === JSON.stringify(["a", "c", "d"]),
);

// 3. Lexicographic order tie-break.
expectOk("lex-order", {
  tasks: [
    { id: "z", duration: 1 },
    { id: "a", duration: 1 },
    { id: "m", duration: 1 },
  ],
}, (o) => JSON.stringify(o.order) === JSON.stringify(["a", "m", "z"]) &&
  JSON.stringify(o.layers) === JSON.stringify([["a", "m", "z"]]),
);

// 4. Zero-duration tasks.
expectOk("zero", { tasks: [{ id: "a", duration: 0 }, { id: "b", duration: 0, dependsOn: ["a"] }] }, (o) =>
  o.totalDuration === 0 && JSON.stringify(o.criticalPath) === JSON.stringify(["a"]),
);

// 5. Critical path lex-smallest with zero-duration intermediate.
expectOk("cp-lex-zero", {
  tasks: [
    { id: "a", duration: 1 },
    { id: "b", duration: 0, dependsOn: ["a"] },
    { id: "c", duration: 1, dependsOn: ["a", "b"] },
  ],
}, (o) => JSON.stringify(o.criticalPath) === JSON.stringify(["a", "b", "c"]),
);

// 6. Disconnected components.
expectOk("disconnected", { tasks: [{ id: "x", duration: 5 }, { id: "y", duration: 2 }] }, (o) =>
  o.totalDuration === 5 && JSON.stringify(o.criticalPath) === JSON.stringify(["x"]),
);

// 7. Empty input.
expectOk("empty", { tasks: [] }, (o) =>
  JSON.stringify(o.order) === "[]" &&
  JSON.stringify(o.layers) === "[]" &&
  JSON.stringify(o.earliest) === "{}" &&
  o.totalDuration === 0 &&
  JSON.stringify(o.criticalPath) === "[]",
);

// 8. dependsOn defaults to [].
expectOk("default-deps", { tasks: [{ id: "a", duration: 2 }] }, (o) =>
  JSON.stringify((o.earliest as any).a) === JSON.stringify({ start: 0, finish: 2 }),
);

// 9. Earliest start/finish with parallelism.
expectOk("parallel", {
  tasks: [
    { id: "a", duration: 2 },
    { id: "b", duration: 3, dependsOn: ["a"] },
    { id: "c", duration: 1, dependsOn: ["a"] },
  ],
}, (o) => {
  const e = o.earliest as any;
  return e.a.finish === 2 && e.b.start === 2 && e.b.finish === 5 && e.c.start === 2 && e.c.finish === 3;
});

// 10. Cycle detection (2-node).
expectErr("cycle-2", { tasks: [{ id: "a", duration: 1, dependsOn: ["b"] }, { id: "b", duration: 1, dependsOn: ["a"] }] }, /cycle/);

// 11. Cycle detection (3-node) prints concrete cycle.
{
  const r = run({ tasks: [
    { id: "a", duration: 1, dependsOn: ["c"] },
    { id: "b", duration: 1, dependsOn: ["a"] },
    { id: "c", duration: 1, dependsOn: ["b"] },
  ] });
  ok("cycle-3", r.code !== 0 && /a -> b -> c -> a/.test(r.stderr), r.stderr.trim());
}

// Validation errors.
expectErr("neg-duration", { tasks: [{ id: "a", duration: -1 }] }, /duration/);
expectErr("nan-duration", { tasks: [{ id: "a", duration: NaN }] }, /duration/);
expectErr("inf-duration", { tasks: [{ id: "a", duration: Infinity }] }, /duration/);
expectErr("empty-id", { tasks: [{ id: "", duration: 1 }] }, /id/);
expectErr("dup-id", { tasks: [{ id: "a", duration: 1 }, { id: "a", duration: 1 }] }, /duplicate/);
expectErr("unknown-dep", { tasks: [{ id: "a", duration: 1, dependsOn: ["b"] }] }, /unknown/);
expectErr("self-dep", { tasks: [{ id: "a", duration: 1, dependsOn: ["a"] }] }, /itself/);
expectErr("dup-dep", { tasks: [{ id: "a", duration: 1 }, { id: "b", duration: 1, dependsOn: ["a", "a"] }] }, /duplicate dependency/);
expectErr("tasks-not-array", { tasks: "x" }, /array/);
expectErr("bad-json", "not json", /invalid JSON/);

// CLI usage errors.
{
  const r = spawnSync("bun", ["run", "src/cli.ts", "foo", "x"], { encoding: "utf8" });
  ok("bad-command", r.status !== 0 && /usage/.test(r.stderr), r.stderr.trim());
}
{
  const r = spawnSync("bun", ["run", "src/cli.ts", "plan", "/tmp/does-not-exist-xyz.json"], { encoding: "utf8" });
  ok("missing-file", r.status !== 0 && /cannot read file/.test(r.stderr), r.stderr.trim());
}

rmSync(dir, { recursive: true, force: true });
console.log(`\n${pass} passed, ${fail} failed`);
if (fail > 0) process.exit(1);

